using System;using System.IO;using System.Xml;using System.Globalization;
namespace BeamScheduleFormatter {
class LengthConfiguration {
 public string Name="Untitled",Version=Engine.Version;public LengthInput Input=new LengthInput();public double FySmall=275,FyLarge=420;public int GradeSmall=40,GradeLarge=60;
 public LengthInput ForDiameter(int diameter,bool top){if(diameter>12&&diameter<16)throw new Exception("Configuration does not assign a grade to 13-15mm bars.");return new LengthInput{Db=diameter,Fy=diameter<=12?FySmall:FyLarge,Simplified=Input.Simplified,Fc=Input.Fc,Cover=Input.Cover,Spacing=Input.Spacing,Ktr=Input.Ktr,AsRatio=Input.AsRatio,Spliced=Input.Spliced,Round=Input.Round,Straight=0,Top=top,Epoxy=Input.Epoxy,Lightweight=Input.Lightweight};}
 public LengthResult Values(int diameter,bool top){return RebarLengths.Calculate(ForDiameter(diameter,top));}
 public double Rounded(double value){return RebarLengths.Up(value,Input.Round);}
 public string Review(){Validate();var b=new System.Text.StringBuilder();b.AppendLine("SPLICE, DEVELOPMENT & HOOKS - CONFIGURATION REVIEW");b.AppendLine("## 01  CONFIGURATION & MATERIALS");b.AppendLine("Configuration: "+Name);b.AppendLine("Method: "+(Input.Simplified?"Sample / NSCP425.4.2.2 simplified other cases":"ACI318M-14 general bond-ratio method"));b.AppendLine("Actual fc="+Input.Fc+"MPa | fy <=12mm="+FySmall+"MPa | fy >=16mm="+FyLarge+"MPa");b.AppendLine("Round UP to "+Input.Round+"mm | "+(Input.Lightweight?"Lightweight lambda0.75":"Normal-weight lambda1")+" | "+(Input.Epoxy?"Epoxy-coated":"Uncoated"));b.AppendLine("Cover TO MAIN BAR="+Input.Cover+"mm | CLEAR spacing="+Input.Spacing+"mm | Ktr="+Input.Ktr+"mm");b.AppendLine("Lap selection: As ratio="+Input.AsRatio+", bars spliced="+Input.Spliced+"%. ClassA requires ratio>=2 and <=50% spliced.");b.AppendLine();b.AppendLine("## 02  DESIGN LENGTH SUMMARY (mm) - ROUNDED UP");b.AppendLine("Other bars                           Top bars                     Compression");b.AppendLine(string.Format("{0,5}{1,10}{2,10}{3,10}{4,10}{5,10}{6,10}{7,10}{8,10}{9,10}","db","Ld","Ldh","Lap A","Lap B","Ld(top)","Lap A","Lap B","Ldc","Lap"));b.AppendLine(new string('-',100));foreach(int d in new[]{10,12,16,20,25,28,32,36}){var a=Values(d,false);var t=Values(d,true);b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,5}{1,10:0.00}{2,10:0.00}{3,10:0.00}{4,10:0.00}{5,10:0.00}{6,10:0.00}{7,10:0.00}{8,10:0.00}{9,10:0.00}",d,Rounded(a.Ld),Rounded(a.Ldh),Rounded(a.LapA),Rounded(a.LapB),Rounded(t.Ld),Rounded(t.LapA),Rounded(t.LapB),Rounded(a.Ldc),Rounded(a.CompressionLap)));}b.AppendLine();b.AppendLine("## 03  HOOK BASIS & ESTIMATOR USE");b.AppendLine("Hook geometry: main90deg tail12db; main180deg tail=max(4db,65mm). Seismic135deg tail=max(6db,75mm).");b.AppendLine("Main inside bend6db for10-25mm,8db for28-36mm; ties4db up to16mm,6db for20-25mm.");b.AppendLine("Ldh is EMBEDMENT, not the hook tail or centerline cut length. Hook cut=arc+tail; beam body length is separate.");b.AppendLine("Estimator uses rounded values per diameter; TOP zones use top values; bottom/SFR use other values.");b.AppendLine("No cover/confinement or excess-steel development reductions applied. Confirm actual splice locations and seismic detailing.");return b.ToString();}
 public void Validate(){if(string.IsNullOrWhiteSpace(Name))throw new Exception("Enter a configuration name.");if((GradeSmall!=40&&GradeSmall!=60)||(GradeLarge!=40&&GradeLarge!=60))throw new Exception("Invalid configuration grades.");foreach(int d in new[]{10,12,16,20,25,28,32,36}){Values(d,false);Values(d,true);}}
 public void Write(XmlElement e){e.SetAttribute("name",Name);e.SetAttribute("appVersion",Version);e.SetAttribute("format","1");double[] values={FySmall,FyLarge,GradeSmall,GradeLarge,Input.Fc,Input.Cover,Input.Spacing,Input.Ktr,Input.AsRatio,Input.Spliced,Input.Round};string[] names={"fySmall","fyLarge","gradeSmall","gradeLarge","fc","cover","spacing","ktr","asRatio","spliced","round"};for(int n=0;n<names.Length;n++)e.SetAttribute(names[n],values[n].ToString("R",CultureInfo.InvariantCulture));e.SetAttribute("db",Input.Db.ToString(CultureInfo.InvariantCulture));e.SetAttribute("top",Input.Top.ToString());e.SetAttribute("straight",Input.Straight.ToString(CultureInfo.InvariantCulture));e.SetAttribute("simplified",Input.Simplified.ToString());e.SetAttribute("epoxy",Input.Epoxy.ToString());e.SetAttribute("lightweight",Input.Lightweight.ToString());}
 public static LengthConfiguration Read(XmlElement e){if(e==null||e.GetAttribute("format")!="1")throw new Exception("Unsupported length configuration.");Func<string,double> number=n=>{double v;if(!double.TryParse(e.GetAttribute(n),NumberStyles.Float,CultureInfo.InvariantCulture,out v)||double.IsNaN(v)||double.IsInfinity(v))throw new Exception("Invalid configuration field: "+n);return v;};var c=new LengthConfiguration{Name=e.GetAttribute("name"),Version=e.GetAttribute("appVersion"),FySmall=number("fySmall"),FyLarge=number("fyLarge"),GradeSmall=(int)number("gradeSmall"),GradeLarge=(int)number("gradeLarge"),Input=new LengthInput{Fc=number("fc"),Cover=number("cover"),Spacing=number("spacing"),Ktr=number("ktr"),AsRatio=number("asRatio"),Spliced=number("spliced"),Round=number("round"),Simplified=e.HasAttribute("simplified")&&bool.Parse(e.GetAttribute("simplified")),Epoxy=bool.Parse(e.GetAttribute("epoxy")),Lightweight=bool.Parse(e.GetAttribute("lightweight"))}};if(e.HasAttribute("db"))c.Input.Db=number("db");if(e.HasAttribute("top"))c.Input.Top=bool.Parse(e.GetAttribute("top"));if(e.HasAttribute("straight"))c.Input.Straight=number("straight");c.Validate();return c;}
 public void Save(string path){Validate();var doc=new XmlDocument();var root=doc.CreateElement("RebarLengthConfiguration");doc.AppendChild(root);Write(root);var table=doc.CreateElement("LengthValuesMM");root.AppendChild(table);foreach(int d in new[]{10,12,16,20,25,28,32,36}){var a=Values(d,false);var b=Values(d,true);var row=doc.CreateElement("Bar");row.SetAttribute("diameter",d.ToString());row.SetAttribute("otherLd",Rounded(a.Ld).ToString(CultureInfo.InvariantCulture));row.SetAttribute("topLd",Rounded(b.Ld).ToString(CultureInfo.InvariantCulture));row.SetAttribute("hookLdh",Rounded(a.Ldh).ToString(CultureInfo.InvariantCulture));row.SetAttribute("otherLap",Rounded(a.Lap).ToString(CultureInfo.InvariantCulture));row.SetAttribute("topLap",Rounded(b.Lap).ToString(CultureInfo.InvariantCulture));row.SetAttribute("hook90ArcTail",Rounded(a.Cut90).ToString(CultureInfo.InvariantCulture));row.SetAttribute("hook180ArcTail",Rounded(a.Cut180).ToString(CultureInfo.InvariantCulture));table.AppendChild(row);}string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{doc.Save(temp);File.Copy(temp,path,true);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static LengthConfiguration Load(string path){var doc=new XmlDocument{XmlResolver=null};using(var r=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=2000000}))doc.Load(r);if(doc.DocumentElement.Name!="RebarLengthConfiguration")throw new Exception("Choose a .rebar-config.xml file.");return Read(doc.DocumentElement);}
}
}
